add_action( 'rest_api_init', function () { register_rest_route( 'nadlan-dbg/v1', '/rw', array( 'methods' => 'GET', 'permission_callback' => function(){ return current_user_can('manage_options'); }, 'callback' => function () { $rules = get_option('rewrite_rules'); $hit = array(); foreach ( (array) $rules as $k => $v ) { if ( strpos($k,'advertiser') !== false || strpos($v,'advertiser') !== false ) { $hit[$k]=$v; } } return array( 'count' => count((array)$rules), 'hit' => $hit, 'qv' => array_key_exists('nadlan_advertiser_center', $GLOBALS['wp']->public_query_vars ?? array()) ); } ) ); } );